// Support both raw body and nested body from n8n webhook
const body = $input.item.json.body ?? $input.item.json;
const { user_id, audio_hash } = body;

if (!user_id || typeof user_id !== 'string' || user_id.trim() === '') {
  throw new Error('Missing or invalid field: user_id (string required)');
}
if (!audio_hash || typeof audio_hash !== 'string' || audio_hash.trim() === '') {
  throw new Error('Missing or invalid field: audio_hash (string required)');
}

const evidence_id = `ev_${Date.now()}_${Math.random().toString(36).slice(2, 7)}`;

return {
  json: {
    evidence_id,
    user:        user_id.trim(),
    hash:        audio_hash.trim(),
    status:      'compiling',
    c2pa_status: 'pending',
    ts:          Date.now(),
    ts_iso:      new Date().toISOString()
  }
};
